export interface Plant {
  id: number;
  name: string;
  category: string;
  price: string;
  image: string;
  description: string;
}

export interface Service {
  id: number;
  title: string;
  description: string;
  icon: React.ReactNode;
}

export enum MessageRole {
  USER = 'user',
  MODEL = 'model'
}

export interface ChatMessage {
  id: string;
  role: MessageRole;
  text: string;
  image?: string; // base64
  isError?: boolean;
}

export interface ChatState {
  messages: ChatMessage[];
  isLoading: boolean;
  isOpen: boolean;
}

import { GoogleGenAI } from "@google/genai";

const apiKey = process.env.API_KEY || '';

// Initialize the client
const ai = new GoogleGenAI({ apiKey });

export const generateGardenAdvice = async (
  prompt: string, 
  imageBase64?: string
): Promise<string> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  try {
    const parts: any[] = [];

    // Add image if present
    if (imageBase64) {
      // Remove data URL prefix if present for the API call
      const cleanBase64 = imageBase64.split(',')[1] || imageBase64;

      parts.push({
        inlineData: {
          mimeType: 'image/jpeg', // Assuming jpeg/png for simplicity from file input
          data: cleanBase64
        }
      });
    }

    // Add text prompt
    parts.push({
      text: prompt
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        role: 'user',
        parts: parts
      },
      config: {
        systemInstruction: `You are the expert Head Horticulturist at Vrtnarstvo Koršič (Koršič Gardening), a family-run garden center in Slovenia with a long tradition. 

        Your tone is warm, professional, encouraging, and deeply knowledgeable about plants, soil, and landscaping.

        Your goals:
        1. Diagnose plant issues from descriptions or images.
        2. Suggest plants from our catalog (seasonal flowers, perennials, herbs, trees).
        3. Offer care tips (watering, light, soil pH).
        4. Be concise but helpful. Use emojis like 🌿, 🌸, 💧 where appropriate.
        5. If asked about location, we are located in Slovenia.

        Always end with a friendly closing like "Happy gardening!" or "Veselo vrtnarjenje!" (Slovenian for Happy gardening).`
      }
    });

    return response.text || "I'm sorry, I couldn't generate a response right now. Please try again.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to get advice from the Plant Doctor.");
  }
};

