import React, { useState } from 'react';
import { Menu, X } from 'lucide-react';
import { Page } from '../App';

interface HeaderProps {
  onNavigate: (page: Page) => void;
  currentPage: Page;
}

export const Header: React.FC<HeaderProps> = ({ onNavigate, currentPage }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleNavClick = (e: React.MouseEvent, target: string, page?: Page) => {
    e.preventDefault();

    // Close mobile menu if open
    setIsMobileMenuOpen(false);

    // If it's a page switch (Home/About)
    if (page) {
      onNavigate(page);
      return;
    }

    // If it's an anchor link like #contact or #catalog
    if (target.startsWith('#')) {
      // If we are on about page and clicking a home-only section (like catalog), go home first
      if (currentPage === 'about' && target !== '#contact') {
        onNavigate('home');
        // Small timeout to allow render before scrolling
        setTimeout(() => {
          const element = document.querySelector(target);
          element?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      } else {
        // Just scroll if on home or if target is footer (#contact)
        const element = document.querySelector(target);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        } else {
          // If element doesn't exist (e.g. on About page trying to find Catalog), go home
          onNavigate('home');
          setTimeout(() => {
            const el = document.querySelector(target);
            el?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
        }
      }
    }
  };

  const navLinks = [
    { name: 'Domov', target: '#home', page: 'home' as Page },
    { name: 'Rastline', target: '#catalog' },
    { name: 'O nas', target: '#about', page: 'about' as Page },
    { name: 'Kontakt', target: '#contact' },
  ];

  // Header becomes solid white when mobile menu is open OR we are on About page (to ensure visibility)
  const isHeaderSolid = isMobileMenuOpen;

  return (
    <header 
      className={`absolute w-full z-50 transition-all duration-300 ${
        isHeaderSolid 
          ? 'bg-white shadow-sm py-2' 
          : 'bg-transparent py-6'
      }`}
    >
      <div className="container mx-auto px-4 md:px-6 flex justify-between items-center">
        {/* Logo Section */}
        <a 
          href="#home" 
          onClick={(e) => handleNavClick(e, '#home', 'home')}
          className="flex items-center gap-2 group"
        >
          <img 
            src="https://vrtnarstvokorsic.si/wp-content/uploads/2016/04/logo-korsic.png" 
            alt="Vrtnarstvo Koršič Logo" 
            className={`h-14 md:h-16 w-auto object-contain transition-all duration-300 group-hover:scale-105 ${
              !isHeaderSolid ? 'brightness-0 invert opacity-90' : ''
            }`}
          />
        </a>

        {/* Desktop Nav */}
        <nav className="hidden md:flex items-center gap-8">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.target}
              onClick={(e) => handleNavClick(e, link.target, link.page)}
              className={`text-sm font-medium transition-colors cursor-pointer ${
                isHeaderSolid 
                  ? 'text-nature-900 hover:text-nature-600' 
                  : (currentPage === 'about' ? 'text-white hover:text-nature-200' : 'text-white hover:text-nature-200')
              } ${link.page === currentPage ? 'underline underline-offset-4 decoration-2 decoration-nature-400' : ''}`}
            >
              {link.name}
            </a>
          ))}
        </nav>

        {/* Mobile Menu Button */}
        <button 
          className={`md:hidden p-2 transition-colors ${
            isHeaderSolid ? 'text-nature-800' : 'text-white'
          }`}
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

