interface CatalogProps {
  onSelectCategory?: (category: Category) => void;
}

export const Catalog: React.FC<CatalogProps> = ({ onSelectCategory }) => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { 
        threshold: 0.01, 
        rootMargin: "-50px" 
      } 
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  const getAnimationClass = (index: number) => {
    const baseClass = "transition-all duration-[1500ms] ease-out";

    if (isVisible) {
      return `${baseClass} opacity-100 translate-x-0 translate-y-0`;
    }

    const mobileHidden = "opacity-0 translate-y-20";

    let desktopHidden = "";
    if (index % 3 === 0) desktopHidden = "md:-translate-x-24 md:translate-y-0"; 
    else if (index % 3 === 1) desktopHidden = "md:translate-y-24 md:translate-x-0"; 
    else desktopHidden = "md:translate-x-24 md:translate-y-0"; 

    return `${baseClass} ${mobileHidden} ${desktopHidden}`;
  };

  return (
    <section id="catalog" className="py-20 bg-white overflow-hidden" ref={sectionRef}>
      <div className="container mx-auto px-4 md:px-6">
        <div className="text-center mb-16">
          <h2 className="text-nature-600 font-semibold tracking-wide uppercase text-sm mb-2">Naša zbirka</h2>
          <h3 className="text-5xl font-serif font-bold text-nature-900 mb-6">NAŠA PONUDBA</h3>
          <p className="text-gray-500 max-w-2xl mx-auto text-lg">
            Z nami bo vaš vrt cvetel! Kliknite na kategorijo za ogled podrobnosti in galerije.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {CATEGORIES.map((item, index) => (
            <div 
              key={item.id} 
              onClick={() => onSelectCategory && onSelectCategory(item)}
              className={`group bg-nature-50/30 rounded-2xl overflow-hidden hover:shadow-xl border border-nature-100 flex flex-col cursor-pointer hover:-translate-y-2 ${getAnimationClass(index)}`}
              style={{ transitionDelay: `${index * 250}ms` }} 
            >
              <div className="relative h-64 overflow-hidden">
                {item.video ? (
                  <video 
                    src={item.video}
                    autoPlay
                    muted
                    loop
                    playsInline
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                  />
                ) : (
                  <img 
                    src={item.image} 
                    alt={item.name} 
                    className={`w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 ${item.imagePosition || 'object-center'}`}
                  />
                )}

                <div className="absolute inset-0 bg-black/10 group-hover:bg-black/0 transition-colors duration-300"></div>
                <div className="absolute top-4 right-4 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full text-xs font-bold text-nature-800 shadow-sm">
                  {item.category}
                </div>
              </div>
              <div className="p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-start mb-2">
                  <h4 className="text-2xl font-serif font-bold text-gray-800 group-hover:text-nature-700 transition-colors">{item.name}</h4>
                </div>
                <p className="text-gray-500 text-sm flex-1 leading-relaxed">{item.description}</p>
                <div className="mt-4 pt-4 border-t border-nature-100/50 flex justify-between items-center">
                    <span className="text-xs text-nature-600 font-medium bg-nature-100 px-3 py-1.5 rounded-full">Oglej si galerijo</span>
                    <span className="text-nature-400 text-sm group-hover:translate-x-1 transition-transform">→</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="text-center mt-16">
          <a 
            href="https://www.google.com/maps/search/?api=1&query=Vrtnarstvo+Koršič+Ščedne+6+Nova+Gorica"
            target="_blank"
            rel="noopener noreferrer"
            className="inline-block bg-nature-800 text-white px-8 py-3 rounded-full hover:bg-nature-700 transition-colors shadow-lg shadow-nature-800/20 font-medium"
          >
            Obiščite nas
          </a>
        </div>
      </div>
    </section>
  );
};

import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';
import { Page } from '../App';

interface HeaderProps {
  onNavigate: (page: Page) => void;
  currentPage: Page;
}

export const Header: React.FC<HeaderProps> = ({ onNavigate, currentPage }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [isDarkContent, setIsDarkContent] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);

      // Home page logic: Text should be white on Hero (dark) and Features (dark), but dark on Catalog (light)
      if (currentPage === 'home') {
        // Hero is usually 100vh. Features is after that.
        // We switch to dark text when user scrolls past roughly 1.5 screen heights (entering light Catalog)
        // Estimation: Hero (100vh) + Features (~600px). 
        // Let's set a trigger point.
        const triggerPoint = window.innerHeight * 1.2; 
        setIsDarkContent(window.scrollY > triggerPoint);
      } else {
        // Other pages (About, Terms, etc.) usually have white background immediately
        setIsDarkContent(true);
      }
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll(); // Initial check
    return () => window.removeEventListener('scroll', handleScroll);
  }, [currentPage]);

  const handleNavClick = (e: React.MouseEvent, target: string, page?: Page) => {
    e.preventDefault();
    setIsMobileMenuOpen(false);

    if (page) {
      onNavigate(page);
      return;
    }

    if (target.startsWith('#')) {
      const lightPages: Page[] = ['about', 'category', 'company-details', 'terms', 'privacy-policy', 'cookies'];
      if (lightPages.includes(currentPage) && target !== '#contact') {
        onNavigate('home');
        setTimeout(() => {
          const element = document.querySelector(target);
          element?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      } else {
        const element = document.querySelector(target);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        } else {
          onNavigate('home');
          setTimeout(() => {
            const el = document.querySelector(target);
            el?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
        }
      }
    }
  };

  const navLinks = [
    { name: 'Domov', target: '#home', page: 'home' as Page },
    { name: 'Rastline', target: '#catalog' },
    { name: 'O nas', target: '#about', page: 'about' as Page },
    { name: 'Kontakt', target: '#contact' },
  ];

  // Logic:
  // Mobile menu open -> Solid White bg needed for menu visibility.
  // Otherwise -> Transparent bg (User request: "brez ozadja").
  // Text color -> depends on isDarkContent (scroll position) OR isMobileMenuOpen.

  const useDarkText = isMobileMenuOpen || isDarkContent;

  return (
    <header 
      className={`fixed top-0 left-0 w-full z-50 transition-all duration-500 ${
        isMobileMenuOpen 
          ? 'bg-white shadow-md py-4' 
          : isScrolled
            ? 'bg-transparent py-3 backdrop-blur-[2px]' // Minimal blur for legibility, no color
            : 'bg-transparent py-6'
      }`}
    >
      <div className="container mx-auto px-4 md:px-6 flex justify-between items-center">
        {/* Logo Section */}
        <a 
          href="#home" 
          onClick={(e) => handleNavClick(e, '#home', 'home')}
          className="flex items-center gap-2 group"
        >
          <img 
            src="https://res.cloudinary.com/dbgh78brl/image/upload/f_auto,q_auto/v1769287031/image-removebg-preview_aqkker.png" 
            alt="Vrtnarstvo Koršič Logo" 
            className={`h-12 md:h-14 w-auto object-contain transition-all duration-300 group-hover:scale-105 ${
              !useDarkText ? 'brightness-0 invert opacity-90 drop-shadow-md' : ''
            }`}
          />
        </a>

        {/* Desktop Nav */}
        <nav className="hidden md:flex items-center gap-8">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.target}
              onClick={(e) => handleNavClick(e, link.target, link.page)}
              className={`text-sm font-medium transition-colors cursor-pointer ${
                useDarkText 
                  ? 'text-nature-900 hover:text-nature-600' 
                  : 'text-white hover:text-nature-200 drop-shadow-md'
              } ${link.page === currentPage && link.page !== 'home' ? 'underline underline-offset-4 decoration-2 decoration-nature-400' : ''}`}
            >
              {link.name}
            </a>
          ))}
        </nav>

        {/* Mobile Menu Button */}
        <button 
          className={`md:hidden p-2 transition-colors ${
            useDarkText ? 'text-nature-800' : 'text-white drop-shadow-md'
          }`}
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Nav */}
      {isMobileMenuOpen && (
        <div className="md:hidden absolute top-full left-0 w-full bg-white shadow-xl border-t border-gray-100 flex flex-col p-6 gap-4 animate-in slide-in-from-top-5">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.target}
              className={`text-lg font-medium py-2 border-b border-gray-50 ${
                 link.page === currentPage ? 'text-nature-600 font-bold' : 'text-gray-800'
              }`}
              onClick={(e) => handleNavClick(e, link.target, link.page)}
            >
              {link.name}
            </a>
          ))}
        </div>
      )}
    </header>
  );
};

