export type Page = 'home' | 'about' | 'category' | 'company-details' | 'terms' | 'privacy-policy' | 'cookies' | 'shop';

import React, { useState, useEffect } from 'react';
import { Menu, X, ShoppingBag } from 'lucide-react';
import { Page } from '../App';

interface HeaderProps {
  onNavigate: (page: Page) => void;
  currentPage: Page;
}

export const Header: React.FC<HeaderProps> = ({ onNavigate, currentPage }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [isDarkContent, setIsDarkContent] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);

      // Home page logic: Text should be white on Hero (dark) and Features (dark), but dark on Catalog (light)
      if (currentPage === 'home') {
        const triggerPoint = window.innerHeight * 1.2; 
        setIsDarkContent(window.scrollY > triggerPoint);
      } else {
        // Other pages (About, Terms, etc.) usually have white background immediately
        setIsDarkContent(true);
      }
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll(); // Initial check
    return () => window.removeEventListener('scroll', handleScroll);
  }, [currentPage]);

  const handleNavClick = (e: React.MouseEvent, target: string, page?: Page) => {
    e.preventDefault();
    setIsMobileMenuOpen(false);

    if (page) {
      onNavigate(page);
      return;
    }

    if (target.startsWith('#')) {
      const lightPages: Page[] = ['about', 'category', 'company-details', 'terms', 'privacy-policy', 'cookies', 'shop'];
      if (lightPages.includes(currentPage) && target !== '#contact') {
        onNavigate('home');
        setTimeout(() => {
          const element = document.querySelector(target);
          element?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      } else {
        const element = document.querySelector(target);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        } else {
          onNavigate('home');
          setTimeout(() => {
            const el = document.querySelector(target);
            el?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
        }
      }
    }
  };

  const navLinks = [
    { name: 'Domov', target: '#home', page: 'home' as Page },
    { name: 'Rastline', target: '#catalog' },
    { name: 'O nas', target: '#about', page: 'about' as Page },
    { name: 'Kontakt', target: '#contact' },
  ];

  const useDarkText = isMobileMenuOpen || isDarkContent;

  return (
    <header 
      className={`fixed top-0 left-0 w-full z-50 transition-all duration-500 ${
        isMobileMenuOpen 
          ? 'bg-white shadow-md py-4' 
          : isScrolled
            ? 'bg-white/90 py-3 backdrop-blur-md shadow-sm text-nature-900' // Changed to white background on scroll for better readability
            : 'bg-transparent py-6'
      }`}
    >
      <div className="container mx-auto px-4 md:px-6 flex justify-between items-center">
        {/* Logo Section */}
        <a 
          href="#home" 
          onClick={(e) => handleNavClick(e, '#home', 'home')}
          className="flex items-center gap-2 group"
        >
          <img 
            src="https://res.cloudinary.com/dbgh78brl/image/upload/f_auto,q_auto/v1769287031/image-removebg-preview_aqkker.png" 
            alt="Vrtnarstvo Koršič Logo" 
            className={`h-12 md:h-14 w-auto object-contain transition-all duration-300 group-hover:scale-105 ${
              !useDarkText && !isScrolled ? 'brightness-0 invert opacity-90 drop-shadow-md' : ''
            }`}
          />
        </a>

        {/* Desktop Nav */}
        <nav className="hidden md:flex items-center gap-8">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.target}
              onClick={(e) => handleNavClick(e, link.target, link.page)}
              className={`text-sm font-medium transition-colors cursor-pointer ${
                useDarkText || isScrolled
                  ? 'text-nature-900 hover:text-nature-600' 
                  : 'text-white hover:text-nature-200 drop-shadow-md'
              } ${link.page === currentPage && link.page !== 'home' ? 'underline underline-offset-4 decoration-2 decoration-nature-400' : ''}`}
            >
              {link.name}
            </a>
          ))}

          {/* Shop Button */}
          <button
            onClick={() => onNavigate('shop')}
            className={`flex items-center gap-2 px-5 py-2.5 rounded-full font-medium transition-all duration-300 transform hover:scale-105 shadow-lg ${
                useDarkText || isScrolled
                ? 'bg-nature-600 text-white hover:bg-nature-700'
                : 'bg-white text-nature-700 hover:bg-nature-50'
            }`}
          >
            <ShoppingBag size={18} />
            <span>Spletna trgovina</span>
          </button>
        </nav>

        {/* Mobile Menu Button */}
        <button 
          className={`md:hidden p-2 transition-colors ${
            useDarkText || isScrolled ? 'text-nature-800' : 'text-white drop-shadow-md'
          }`}
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Nav */}
      {isMobileMenuOpen && (
        <div className="md:hidden absolute top-full left-0 w-full bg-white shadow-xl border-t border-gray-100 flex flex-col p-6 gap-4 animate-in slide-in-from-top-5">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.target}
              className={`text-lg font-medium py-2 border-b border-gray-50 ${
                 link.page === currentPage ? 'text-nature-600 font-bold' : 'text-gray-800'
              }`}
              onClick={(e) => handleNavClick(e, link.target, link.page)}
            >
              {link.name}
            </a>
          ))}
          <button
            onClick={() => {
                onNavigate('shop');
                setIsMobileMenuOpen(false);
            }}
            className="mt-2 w-full flex items-center justify-center gap-2 bg-nature-600 text-white py-3 rounded-xl font-medium hover:bg-nature-700 active:scale-95 transition-all"
          >
            <ShoppingBag size={20} />
            Spletna trgovina
          </button>
        </div>
      )}
    </header>
  );
};

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
import { Catalog } from './components/Catalog';
import { Features } from './components/Features';
import { Benefits } from './components/Benefits';
import { Gallery } from './components/Gallery';
import { Testimonials } from './components/Testimonials';
import { SocialCta } from './components/SocialCta';
import { Footer } from './components/Footer';
import { PlantDoctor } from './components/PlantDoctor';
import { AboutPage } from './components/AboutPage';
import { CategoryPage } from './components/CategoryPage';
import { CompanyDetailsPage } from './components/CompanyDetailsPage';
import { TermsPage } from './components/TermsPage';
import { PrivacyPolicyPage } from './components/PrivacyPolicyPage';
import { CookiesPage } from './components/CookiesPage';
import { ShopPage } from './components/ShopPage';
import { CookieConsent } from './components/CookieConsent';
import { Preloader } from './components/Preloader';
import { Category, Page } from './types';

function App() {
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Fallback timer: če se video iz kakršnega koli razloga ne naloži v 4 sekundah, vseeno pokaži stran
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 4000);
    return () => clearTimeout(timer);
  }, []);

  const handleVideoLoaded = () => {
    // Ko se iframe naloži, počakamo še malo (1s), da video zagotovo začne teči (buffering),
    // preden umaknemo preloader. To prepreči "zelen ekran".
    setTimeout(() => {
      setIsLoading(false);
    }, 1200);
  };

  const handleNavigate = (page: Page) => {
    setCurrentPage(page);
    setSelectedCategory(null); // Clear category when navigating to main pages
    window.scrollTo(0, 0);
  };

  const handleCategorySelect = (category: Category) => {
    setSelectedCategory(category);
    setCurrentPage('category');
    window.scrollTo(0, 0);
  };

  const handleBackFromCategory = () => {
    setSelectedCategory(null);
    setCurrentPage('home'); // Return to home where catalog is
    // Optional: scroll to catalog section
    setTimeout(() => {
      document.getElementById('catalog')?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  return (
    <div className="min-h-screen flex flex-col font-sans">
      <Preloader isLoading={isLoading} />

      {/* 
        Header renderiramo, a ga skrijemo z opacity dokler se ne naloži, 
        da preprečimo "skok" vsebine, če bi ga kondicijsko renderirali.
      */}
      <div className={`transition-opacity duration-1000 ${isLoading ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
        <Header onNavigate={handleNavigate} currentPage={currentPage} />

        <main>
          {currentPage === 'shop' ? (
            <ShopPage />
          ) : currentPage === 'category' && selectedCategory ? (
            <CategoryPage category={selectedCategory} onBack={handleBackFromCategory} />
          ) : currentPage === 'about' ? (
            <AboutPage />
          ) : currentPage === 'company-details' ? (
            <CompanyDetailsPage />
          ) : currentPage === 'terms' ? (
            <TermsPage />
          ) : currentPage === 'privacy-policy' ? (
            <PrivacyPolicyPage />
          ) : currentPage === 'cookies' ? (
            <CookiesPage />
          ) : (
            /* Home Page */
            <>
              <Hero onNavigate={handleNavigate} onVideoLoaded={handleVideoLoaded} />
              <Features />
              {/* Pass handleCategorySelect to Catalog */}
              <Catalog onSelectCategory={handleCategorySelect} />
              <Benefits />
              <Gallery />
              <Testimonials />
              <SocialCta />
            </>
          )}
        </main>

        <CookieConsent onNavigate={handleNavigate} />
        <Footer onNavigate={handleNavigate} onSelectCategory={handleCategorySelect} />
        <PlantDoctor />
      </div>
    </div>
  );
}

export default App;

