// OPOZORILO: Tukaj zamenjaj z tvojimi pravimi podatki iz Supabase nadzorne plošče
// Settings -> API
const SUPABASE_URL = 'TVOJ_SUPABASE_URL_TUKAJ'; 
const SUPABASE_ANON_KEY = 'TVOJ_SUPABASE_ANON_KEY_TUKAJ';

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

export const fetchProductsFromSupabase = async (): Promise<Product[]> => {
  try {
    // Predpostavljamo, da se tabela imenuje 'products'
    let { data, error } = await supabase
      .from('products')
      .select('*');

    if (error) {
      console.error("Napaka pri pridobivanju izdelkov:", error);
      return [];
    }

    if (!data) return [];

    // Preslikava podatkov, če se imena stolpcev v bazi razlikujejo od vmesnika
    // Če si v bazi uporabil snake_case (npr. in_stock), typescript pa rabi camelCase (inStock)
    return data.map((item: any) => ({
      id: item.id.toString(),
      name: item.name,
      description: item.description,
      price: item.price,
      category: item.category,
      image: item.image,
      tag: item.tag,
      inStock: item.in_stock ?? true // Privzeto true, če stolpec ne obstaja
    }));
  } catch (err) {
    console.error("Nepričakovana napaka:", err);
    return [];
  }
};

