import { createClient } from '@supabase/supabase-js';
import { Product } from '../types';

// ------------------------------------------------------------------
// NAVODILA ZA POVEZAVO:
// 1. Pojdite na Supabase -> Project Settings -> API
// 2. Kopirajte "Project URL" in ga prilepite spodaj namesto 'https://tvoj-projekt.supabase.co'
// 3. Kopirajte "anon public" key in ga prilepite spodaj namesto 'tvoj-anon-key'
// ------------------------------------------------------------------

const SUPABASE_URL = 'https://tvoj-projekt.supabase.co'; 
const SUPABASE_ANON_KEY = 'tvoj-anon-key';

// Preprosta validacija, da preprečimo "crash" aplikacije, če podatki niso vpisani
const isValidSetup = () => {
  return SUPABASE_URL.startsWith('https://') && !SUPABASE_URL.includes('tvoj-projekt');
};

// Klienta ustvarimo le, če so podatki pravilni. Sicer nastavimo na null.
export const supabase = isValidSetup() 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) 
  : null;

export const fetchProductsFromSupabase = async (): Promise<Product[]> => {
  // Če baza ni povezana, vrnemo prazen seznam. 
  // ShopPage.tsx bo v tem primeru avtomatsko naložil testne izdelke (fallback).
  if (!supabase) {
    console.warn("Supabase ni povezan. Prikazujem lokalne testne izdelke. Uredite services/supabase.ts za povezavo.");
    return [];
  }

  try {
    let { data, error } = await supabase
      .from('products')
      .select('*');

    if (error) {
      console.error("Napaka pri branju iz Supabase:", error.message);
      return [];
    }

    if (!data) return [];

    // Preslikava podatkov iz baze v naš format
    return data.map((item: any) => ({
      id: item.id.toString(),
      name: item.name,
      description: item.description,
      price: item.price,
      category: item.category,
      image: item.image,
      tag: item.tag,
      inStock: item.in_stock ?? true
    }));
  } catch (err) {
    console.error("Nepričakovana napaka pri povezavi:", err);
    return [];
  }
};

