import React, { useEffect, useState } from 'react';
import { ShoppingBag, Truck, ShieldCheck, Leaf, ArrowRight, Search, Loader2, AlertCircle } from 'lucide-react';
import { formatPrice } from '../data/products';
import { useCart } from '../context/CartContext';
import { fetchProductsFromSupabase } from '../services/supabase';
import { Product } from '../types';
import { PRODUCTS as FALLBACK_PRODUCTS } from '../data/products';

export const ShopPage: React.FC = () => {
  const { addToCart } = useCart();
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUsingFallback, setIsUsingFallback] = useState(false);

  useEffect(() => {
    window.scrollTo(0, 0);

    const loadData = async () => {
      setIsLoading(true);
      const data = await fetchProductsFromSupabase();

      // LOGIKA:
      // Če dobimo null, pomeni napako v povezavi -> uporabimo Demo podatke (Fallback).
      // Če dobimo [], pomeni da povezava dela, a ni izdelkov (ali RLS blokira) -> Prikazemo prazno stanje, ne fallbacka.

      if (data === null) {
