import { createClient } from '@supabase/supabase-js';
import { Product } from '../types';

// ------------------------------------------------------------------
// KONFIGURACIJA SUPABASE
// ------------------------------------------------------------------

const SUPABASE_URL = 'https://nptcxgecayuakaqloujy.supabase.co'; 
const SUPABASE_ANON_KEY = 'sb_publishable_Q5VpvZ2hAnzKwSTq7ZnspA_nquLe2CN';

// Validacija: Preverimo, če je uporabnik vnesel pravi URL (mora se začeti s https://)
const isValidSetup = () => {
  return SUPABASE_URL && SUPABASE_URL.startsWith('https://') && !SUPABASE_URL.includes('PRILEPI_');
};

// Ustvarimo klienta le, če so podatki pravilni. Sicer je null.
export const supabase = isValidSetup() 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) 
  : null;

interface SupabaseResult {
  data: Product[];
  error: string | null;
  details?: string;
}

// Vrnemo objekt z data in error za lažje debugiranje v UI
export const fetchProductsFromSupabase = async (): Promise<SupabaseResult> => {
  // Če konfiguracija ni pravilna
  if (!supabase) {
    return { 
      data: [], 
      error: "Supabase ni konfiguriran (Manjka URL ali Key v services/supabase.ts)." 
    };
  }

  try {
    console.log("Poskušam prebrati izdelke iz Supabase...");

    // Branje iz tabele 'products'
    let { data, error } = await supabase
      .from('products')
      .select('*');

    if (error) {
      console.error("SUPABASE NAPAKA:", error);
      // Vrnemo točno sporočilo napake
      return { 
        data: [], 
        error: error.message,
        details: error.details || error.hint 
      };
    }

    if (!data) {
      return { data: [], error: null };
    }

    // Preslikava podatkov iz baze v format aplikacije
    const mappedProducts = data.map((item: any) => ({
      id: item.id?.toString() || Math.random().toString(),
      name: item.name || 'Neznan izdelek',
      description: item.description || '',
      price: Number(item.price) || 0,
      category: item.category || 'Ostalo',
      image: item.image || 'https://via.placeholder.com/400x400?text=Ni+slike',
      tag: item.tag || null,
      inStock: item.in_stock ?? true
    }));

    return { data: mappedProducts, error: null };

  } catch (err: any) {
    console.error("Nepričakovana napaka pri povezavi:", err);
    return { 
      data: [], 
      error: "Nepričakovana napaka v aplikaciji: " + (err.message || String(err)) 
    };
  }
};

