// Helper component for individual product card with variations
const ProductCard: React.FC<{ 
  group: ShopProduct[], 
  addToCart: (p: ShopProduct) => void 
}> = ({ group, addToCart }) => {
  // Sort variations by price (usually implies size)
  const sortedGroup = [...group].sort((a, b) => a.price - b.price);
  const [selectedProduct, setSelectedProduct] = useState<ShopProduct>(sortedGroup[0]);

  // If the group has multiple items, it means we have variations.
  // If a single item has a 'variation' field, we show it too.
  const hasVariations = sortedGroup.length > 1;

  return (
    <div className="bg-white rounded-2xl overflow-hidden border border-gray-100 shadow-sm hover:shadow-xl transition-all duration-300 group flex flex-col h-full">
      <div className="relative aspect-square overflow-hidden bg-gray-100">
        {selectedProduct.image_url ? (
          <img 
            src={selectedProduct.image_url} 
            alt={selectedProduct.name} 
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-gray-300">
            <ShoppingBag size={40} />
          </div>
        )}
        <div className="absolute top-3 right-3 bg-white/90 backdrop-blur-sm px-2 py-1 rounded text-xs font-bold text-nature-800 shadow-sm">
          {selectedProduct.category}
        </div>
      </div>

      <div className="p-5 flex flex-col flex-1">
        <h3 className="font-serif font-bold text-xl text-gray-900 mb-2 group-hover:text-nature-600 transition-colors">
          {selectedProduct.name}
        </h3>
        <p className="text-gray-500 text-sm mb-4 line-clamp-2 flex-1">
          {selectedProduct.description}
        </p>

        {/* Variation Selector */}
        {hasVariations && (
          <div className="mb-4">
            <span className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2 block">Izberite velikost:</span>
            <div className="flex flex-wrap gap-2">
              {sortedGroup.map((variant) => (
                <button
                  key={variant.id}
                  onClick={() => setSelectedProduct(variant)}
                  className={`px-3 py-1 rounded-full text-xs font-bold border transition-all ${
                    selectedProduct.id === variant.id
                      ? 'bg-nature-600 text-white border-nature-600 shadow-sm'
                      : 'bg-white text-gray-600 border-gray-200 hover:border-nature-400'
                  }`}
                >
                  {variant.variation || 'Standard'}
                </button>
              ))}
            </div>
          </div>
        )}

        <div className="flex items-center justify-between mt-auto pt-4 border-t border-gray-50">
          <div className="flex flex-col">
             <span className="text-xl font-bold text-nature-700">{(selectedProduct.price || 0).toFixed(2)} €</span>
             {hasVariations && <span className="text-xs text-gray-400">{selectedProduct.variation}</span>}
          </div>
          <button 
            onClick={() => addToCart(selectedProduct)}
            className="bg-nature-100 text-nature-700 p-2.5 rounded-full hover:bg-nature-600 hover:text-white transition-all shadow-sm active:scale-95 flex items-center justify-center gap-2 group/btn"
            title="Dodaj v košarico"
          >
              <Plus size={20} className="group-hover/btn:hidden" />
              <span className="hidden group-hover/btn:inline text-sm font-bold px-2">Dodaj</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export const ShopPage: React.FC = () => {
  const [productGroups, setProductGroups] = useState<ShopProduct[][]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('Vse');
  const [categories, setCategories] = useState<string[]>(['Vse']);

  const { addToCart, cart, isCartOpen, setIsCartOpen, removeFromCart, updateQuantity, totalPrice } = useCart();

  useEffect(() => {
    fetchProducts();
    window.scrollTo(0, 0);
  }, []);

  const fetchProducts = async () => {
    try {
      const { data, error } = await supabase
        .from('products')
        .select('*');

      if (error) {
        console.error('Error fetching products:', error);
        setProductGroups([]);
      } else if (data) {
        const productsData = data as ShopProduct[];

        // Group products by name
        const groups: Record<string, ShopProduct[]> = {};
        productsData.forEach(p => {
            // Use name as key. Normalize simple differences if needed, but strict name match is safest.
            const key = p.name; 
            if (!groups[key]) groups[key] = [];
            groups[key].push(p);
        });

        setProductGroups(Object.values(groups));

        // Extract unique categories
        const uniqueCategories = ['Vse', ...Array.from(new Set(productsData.map((p) => p.category)))];
        setCategories(uniqueCategories);
      }
    } catch (err) {
      console.error('Supabase connection error:', err);
    } finally {
      setLoading(false);
    }
  };

  const filteredGroups = productGroups.filter(group => {
    // Check if any product in the group matches the criteria
    const firstProduct = group[0];
    const matchesSearch = firstProduct.name?.toLowerCase().includes(searchTerm.toLowerCase()) || 
