import React from 'react';

export interface Plant {
  id: number;
  name: string;
  category: string;
  price: string;
  image: string;
  description: string;
}

export interface ShopProduct {
  id: number;
  name: string;
  description: string;
  price: number;
  image_url: string;
  category: string;
  variation?: string; // e.g. "Mala", "Velika"
  size?: string;      // e.g. "20L", "45L" from CSV import
  stock?: number;     // Zaloga
}

export interface Service {
  id: number;
  title: string;
  description: string;
  icon: React.ReactNode;
}

export interface Category {
  id: number;
  name: string;
  category: string;
  image: string;
  video?: string;
  imagePosition?: string;
  description: string;
  galleryImages?: { url: string; title: string }[]; // Updated to support titles
}

export enum MessageRole {
  USER = 'user',
  MODEL = 'model'
}

export interface ChatMessage {
  id: string;
  role: MessageRole;
  text: string;
  image?: string; // base64
  isError?: boolean;
}

export interface ChatState {
  messages: ChatMessage[];
  isLoading: boolean;
  isOpen: boolean;
}

import React, { useEffect, useState } from 'react';
import { ShoppingBag, Search, Loader2, X, Trash2, Plus, Minus, ShoppingCart, Check, Info } from 'lucide-react';
import { supabase } from '../services/supabase';
import { ShopProduct } from '../types';
import { useCart } from '../context/CartContext';

// --- PRODUCT MODAL COMPONENT ---
const ProductModal: React.FC<{
  group: ShopProduct[];
  isOpen: boolean;
  onClose: () => void;
  addToCart: (p: ShopProduct, qty: number) => void;
}> = ({ group, isOpen, onClose, addToCart }) => {
  // Sort by price
  const sortedGroup = [...group].sort((a, b) => a.price - b.price);
  const [selectedVariant, setSelectedVariant] = useState<ShopProduct>(sortedGroup[0]);
  const [quantity, setQuantity] = useState(1);

  // Reset selected variant and quantity when group changes
  useEffect(() => {
    if (group.length > 0) {
      const sorted = [...group].sort((a, b) => a.price - b.price);
      setSelectedVariant(sorted[0]);
      setQuantity(1);
    }
  }, [group]);

  if (!isOpen) return null;

  // Check for size OR variation
  const hasVariations = sortedGroup.length > 1 || !!sortedGroup[0].size || !!sortedGroup[0].variation;

  // Check stock (if stock is explicitly 0, it's out of stock. Undefined/null is assumed in stock)
  const isOutOfStock = typeof selectedVariant.stock === 'number' && selectedVariant.stock <= 0;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
