               alt={selectedVariant.name} 
               className={`w-full h-full object-cover absolute inset-0 ${isOutOfStock ? 'grayscale opacity-80' : ''}`}
             />
           ) : (
             <div className="w-full h-full flex items-center justify-center text-gray-300">
               <ShoppingBag size={64} />
             </div>
           )}
           <div className="absolute top-4 left-4 bg-white/90 backdrop-blur-sm px-3 py-1.5 rounded-lg text-sm font-bold text-nature-800 shadow-sm">
              {selectedVariant.category}
           </div>

           {isOutOfStock && (
               <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white/90 backdrop-blur-md px-6 py-3 rounded-xl shadow-xl border-2 border-red-100">
                   <span className="text-red-600 font-bold text-lg uppercase tracking-wider flex items-center gap-2">
                       <X size={24} /> Ni na zalogi
                   </span>
               </div>
           )}
        </div>

        {/* Info Side */}
        <div className="w-full md:w-1/2 p-8 md:p-10 flex flex-col">
          <h2 className="text-3xl md:text-4xl font-serif font-bold text-nature-900 mb-4">
            {selectedVariant.name}
          </h2>

          <div className="mb-6 flex items-baseline gap-3">
            <span className={`text-3xl font-bold ${isOutOfStock ? 'text-gray-400' : 'text-nature-600'}`}>
              {(selectedVariant.price || 0).toFixed(2)} €
            </span>
            {hasVariations && (selectedVariant.size || selectedVariant.variation) && (
              <span className="text-lg text-gray-400 font-medium">
                 / {selectedVariant.size || selectedVariant.variation}
              </span>
            )}
          </div>

          <div className="prose prose-sm text-gray-600 mb-8 leading-relaxed">
            <p>{selectedVariant.description}</p>
          </div>

          {/* Variations */}
          {hasVariations && (
            <div className="mb-6">
              <span className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3 block">
                Izberite velikost:
              </span>
              <div className="flex flex-wrap gap-3">
                {sortedGroup.map((variant) => {
                  const variantOutOfStock = typeof variant.stock === 'number' && variant.stock <= 0;
                  return (
                    <button
                        key={variant.id}
                        onClick={() => setSelectedVariant(variant)}
                        className={`px-4 py-2 rounded-xl text-sm font-bold border-2 transition-all relative overflow-hidden ${
                        selectedVariant.id === variant.id
                            ? 'bg-nature-50 border-nature-600 text-nature-700'
                            : 'bg-white border-gray-100 text-gray-600 hover:border-gray-300'
                        } ${variantOutOfStock ? 'opacity-60' : ''}`}
                    >
                        {variant.size || variant.variation || 'Standard'}
                        <span className="block text-xs font-normal opacity-70 mt-0.5">
                        {(variant.price || 0).toFixed(2)} €
                        </span>
                        {variantOutOfStock && selectedVariant.id !== variant.id && (
                            <div className="absolute inset-0 flex items-center justify-center bg-gray-50/80 backdrop-blur-[1px]">
                                <X size={16} className="text-red-400" />
                            </div>
                        )}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* Quantity Selector */}
          <div className={`mb-8 ${isOutOfStock ? 'opacity-50 pointer-events-none' : ''}`}>
            <span className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3 block">
                Količina:
            </span>
            <div className="flex items-center gap-4 bg-gray-50 rounded-xl w-max p-2 border border-gray-100">
                <button 
                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                    className="w-10 h-10 flex items-center justify-center bg-white rounded-lg shadow-sm text-nature-600 hover:bg-nature-50 hover:text-nature-800 transition-all active:scale-95 disabled:opacity-50"
                    disabled={quantity <= 1}
                >
                    <Minus size={18} />
                </button>
                <span className="font-bold text-xl w-8 text-center text-gray-900">{quantity}</span>
                <button 
                    onClick={() => setQuantity(quantity + 1)}
                    className="w-10 h-10 flex items-center justify-center bg-white rounded-lg shadow-sm text-nature-600 hover:bg-nature-50 hover:text-nature-800 transition-all active:scale-95"
                >
                    <Plus size={18} />
                </button>
            </div>
          </div>

          {/* Action Button */}
          <div className="mt-auto pt-6 border-t border-gray-100">
            <button 
              onClick={() => {
                if (!isOutOfStock) {
                    addToCart(selectedVariant, quantity);
                    onClose();
                }
              }}
              disabled={isOutOfStock}
              className={`w-full py-4 rounded-xl font-bold text-lg transition-all shadow-lg flex items-center justify-center gap-2 group ${
                isOutOfStock 
                  ? 'bg-gray-100 text-gray-400 cursor-not-allowed shadow-none' 
                  : 'bg-nature-600 text-white hover:bg-nature-700 shadow-nature-600/20'
              }`}
            >
              {isOutOfStock ? (
                  <>Ni na zalogi <X size={24} /></>
              ) : (
                  <>
                    <Plus size={24} className="group-hover:scale-110 transition-transform" />
                    Dodaj v košarico ({quantity})
                  </>
              )}
            </button>
            <p className="text-center text-xs text-gray-400 mt-3 flex items-center justify-center gap-1">
              {isOutOfStock ? (
                  <span className="text-red-500 font-medium flex items-center gap-1">
                      <X size={12}/> Izdelek trenutno ni dobavljiv
                  </span>
              ) : (
                  <span className="flex items-center gap-1"><Check size={12} /> Na zalogi v vrtnariji</span>
              )}
            </p>
          </div>

        </div>
      </div>
    </div>
  );
};


// --- PRODUCT CARD COMPONENT ---
const ProductCard: React.FC<{ 
  group: ShopProduct[], 
  addToCart: (p: ShopProduct, qty: number) => void,
  onOpenModal: (group: ShopProduct[]) => void
}> = ({ group, addToCart, onOpenModal }) => {
  // Sort variations by price (usually implies size)
  const sortedGroup = [...group].sort((a, b) => a.price - b.price);
  const [selectedProduct, setSelectedProduct] = useState<ShopProduct>(sortedGroup[0]);

  // Check for size OR variation presence in the group
  const hasVariations = sortedGroup.length > 1;

  // Check stock
  const isOutOfStock = typeof selectedProduct.stock === 'number' && selectedProduct.stock <= 0;

  const handleOpenClick = () => {
    onOpenModal(group);
  };

  return (
    <div className="bg-white rounded-2xl overflow-hidden border border-gray-100 shadow-sm hover:shadow-xl transition-all duration-300 group flex flex-col h-full relative">

      {/* Clickable Area for Modal */}
      <div className="cursor-pointer" onClick={handleOpenClick}>
        <div className="relative aspect-square overflow-hidden bg-gray-100">
            {selectedProduct.image_url ? (
            <img 
                src={selectedProduct.image_url} 
                alt={selectedProduct.name} 
                className={`w-full h-full object-cover transition-transform duration-700 group-hover:scale-110 ${isOutOfStock ? 'grayscale opacity-90' : ''}`}
            />
            ) : (
            <div className="w-full h-full flex items-center justify-center text-gray-300">
                <ShoppingBag size={40} />
            </div>
            )}

            {/* Overlay if out of stock */}
            {isOutOfStock && (
                <div className="absolute inset-0 bg-white/50 backdrop-blur-[2px] flex items-center justify-center z-20">
                    <div className="bg-red-500 text-white px-3 py-1 rounded-full text-xs font-bold shadow-lg flex items-center gap-1">
                        <X size={14} /> NI ZALOGE
                    </div>
                </div>
            )}

            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 transition-colors duration-300 flex items-center justify-center z-10">
                {!isOutOfStock && (
                    <div className="bg-white/90 backdrop-blur px-4 py-2 rounded-full text-nature-900 font-bold text-sm opacity-0 translate-y-4 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300 shadow-lg flex items-center gap-2">
                        <Info size={16} /> Poglej podrobnosti
                    </div>
                )}
            </div>

            <div className="absolute top-3 right-3 bg-white/90 backdrop-blur-sm px-2 py-1 rounded text-xs font-bold text-nature-800 shadow-sm pointer-events-none z-20">
            {selectedProduct.category}
            </div>
        </div>

        <div className="p-5 pb-0">
            <h3 className={`font-serif font-bold text-xl mb-2 transition-colors ${isOutOfStock ? 'text-gray-400' : 'text-gray-900 group-hover:text-nature-600'}`}>
            {selectedProduct.name}
            </h3>
            <p className="text-gray-500 text-sm mb-4 line-clamp-2">
            {selectedProduct.description}
            </p>
        </div>
      </div>

      <div className="px-5 pb-5 flex flex-col flex-1">
        {/* Variation Selector (Mini) */}
        {hasVariations && (
          <div className="mb-4 mt-auto">
            <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2 block">Velikost:</span>
            <div className="flex flex-wrap gap-2">
              {sortedGroup.map((variant) => {
                const varStockZero = typeof variant.stock === 'number' && variant.stock <= 0;
                return (
                  <button
                    key={variant.id}
                    onClick={(e) => {
                        e.stopPropagation(); // Prevent opening modal
                        setSelectedProduct(variant);
                    }}
                    className={`px-2 py-1 rounded-md text-xs font-bold border transition-all ${
                      selectedProduct.id === variant.id
                        ? 'bg-nature-50 text-nature-700 border-nature-200'
                        : 'bg-white text-gray-500 border-gray-100 hover:border-gray-300'
                    } ${varStockZero ? 'opacity-50 decoration-slate-400' : ''}`}
                  >
                    {variant.size || variant.variation || 'Std'}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        <div className={`flex items-center justify-between pt-4 border-t border-gray-50 ${!hasVariations ? 'mt-auto' : ''}`}>
          <div className="flex flex-col">
             <span className={`text-xl font-bold ${isOutOfStock ? 'text-gray-300' : 'text-nature-700'}`}>{(selectedProduct.price || 0).toFixed(2)} €</span>
             {hasVariations && (
                 <span className="text-xs text-gray-400">
                     {selectedProduct.size || selectedProduct.variation}
                 </span>
             )}
          </div>
          <button 
            onClick={(e) => {
                e.stopPropagation(); // Prevent opening modal
                if (!isOutOfStock) addToCart(selectedProduct, 1);
            }}
            disabled={isOutOfStock}
            className={`p-2.5 rounded-full transition-all shadow-sm active:scale-95 flex items-center justify-center gap-2 group/btn z-10 ${
                isOutOfStock 
                ? 'bg-gray-100 text-gray-400 cursor-not-allowed' 
                : 'bg-nature-100 text-nature-700 hover:bg-nature-600 hover:text-white'
            }`}
