          >
              {isOutOfStock ? <X size={20} /> : <Plus size={20} className="group-hover/btn:hidden" />}
              <span className={`hidden group-hover/btn:inline text-sm font-bold px-2`}>
                  {isOutOfStock ? 'Ni zaloge' : 'Dodaj'}
              </span>
          </button>
        </div>
      </div>
    </div>
  );
};

